<template><div class="page"><div class="page-head"><div><h2>用户与权限</h2><p>角色决定功能权限与 DataScope；AI Agent同样继承当前登录用户的权限范围。</p></div><el-button type="primary" v-if="auth.has('system:user:write')" @click="visible=true">新增用户</el-button></div><el-table :data="rows" stripe><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="username" label="账号"/><el-table-column prop="realName" label="姓名"/><el-table-column prop="deptId" label="部门ID"/><el-table-column prop="securityLevel" label="密级"/><el-table-column prop="status" label="状态"><template #default="s"><el-tag :type="s.row.status?'success':'danger'">{{s.row.status?'启用':'禁用'}}</el-tag></template></el-table-column></el-table><el-row :gutter="16" style="margin-top:16px"><el-col :span="12"><el-card><template #header>角色 / 数据范围</template><el-table :data="roles"><el-table-column prop="roleName" label="角色"/><el-table-column prop="roleCode" label="编码"/><el-table-column prop="dataScope" label="DataScope"/><el-table-column prop="readonlyFlag" label="只读"><template #default="s">{{s.row.readonlyFlag?'是':'否'}}</template></el-table-column></el-table></el-card></el-col><el-col :span="12"><el-card><template #header>部门</template><el-table :data="departments"><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="parentId" label="上级ID"/><el-table-column prop="deptName" label="部门名称"/></el-table></el-card></el-col></el-row><el-dialog v-model="visible" title="新增用户" width="520px"><el-form label-width="85px"><el-form-item label="账号"><el-input v-model="form.username"/></el-form-item><el-form-item label="密码"><el-input type="password" show-password v-model="form.password"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.realName"/></el-form-item><el-form-item label="部门"><el-select v-model="form.deptId" style="width:100%"><el-option v-for="d in departments" :key="d.id" :label="d.deptName" :value="d.id"/></el-select></el-form-item><el-form-item label="密级"><el-input-number v-model="form.securityLevel" :min="1" :max="5"/></el-form-item><el-form-item label="角色"><el-select v-model="form.roleIds" multiple style="width:100%"><el-option v-for="r in roles" :key="r.id" :label="r.roleName+' ('+r.dataScope+')'" :value="r.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">创建</el-button></template></el-dialog></div></template>
<script setup>import{ref,onMounted}from'vue';import{ElMessage}from'element-plus';import{api}from'../api';import{useAuthStore}from'../stores/auth';const auth=useAuthStore(),rows=ref([]),roles=ref([]),departments=ref([]),visible=ref(false);const form=ref({username:'',password:'Admin@123',realName:'',deptId:2,securityLevel:1,roleIds:[4]});async function load(){const [u,r,d]=await Promise.all([api.users(),api.roles(),api.departments()]);rows.value=u||[];roles.value=r||[];departments.value=d||[]}async function save(){await api.createUser(form.value);ElMessage.success('用户创建成功');visible.value=false;form.value={username:'',password:'Admin@123',realName:'',deptId:2,securityLevel:1,roleIds:[4]};load()}onMounted(load)</script>
